from solution import excerpt
assert [excerpt('a猫🙂z',n) for n in [0,1,3,4,7,8,9]]==['','a','a','a猫','a猫','a猫🙂','a猫🙂z']
assert excerpt('',3)==''
try: excerpt('x',-1)
except ValueError: pass
else: raise AssertionError('negative accepted')

from solution import LRU
c=LRU(2);c.put('a',1);c.put('b',2);assert c.get('a')==1;c.put('c',3);assert c.keys()==['a','c'];assert c.get('b',9)==9;c.put('a',4);assert c.keys()==['c','a'];assert c.get('a')==4
z=LRU(0);z.put('x',1);assert z.keys()==[]
try: LRU(-1)
except ValueError: pass
else: raise AssertionError('negative accepted')

from solution import load
assert load(['base.ini','override.ini'])=={'server':{'host':'localhost','port':'81','literal':'50%','debug':'yes'}}
try: load(['absent.ini'])
except FileNotFoundError: pass
else: raise AssertionError('missing ignored')

from solution import safe_member
for p in ['', '/', '/x', '../x','a/../b','C:/x','a\\b','a\x00b']: assert not safe_member(p),repr(p)
for p in ['a/b','./a','a//b','abc..def','a:b/c']: assert safe_member(p),p

from solution import transfer
import sqlite3
c=sqlite3.connect(':memory:');c.execute('create table accounts(id text primary key,balance integer)');c.executemany('insert into accounts values(?,?)',[('a',10),('b',2)]);c.commit();transfer(c,'a','b',3);assert c.execute('select * from accounts order by id').fetchall()==[('a',7),('b',5)]
for args in [('a','b',8),('a','z',1),('a','a',1),('a','b',True),('a','b',0)]:
 try: transfer(c,*args)
 except ValueError: pass
 else: raise AssertionError(args)
 assert c.execute('select balance from accounts order by id').fetchall()==[(7,),(5,)]

from solution import parse_chunks
s='{"name":"猫"}\n\n[1,2]\ntrue'.encode();assert parse_chunks([s[i:i+1] for i in range(len(s))])==[{'name':'猫'},[1,2],True]
assert parse_chunks([])==[]
for chunks in [[b'{bad}'],[b'\xff']]:
 try: parse_chunks(chunks)
 except ValueError: pass
 else: raise AssertionError('invalid accepted')

