from solution import resolve
d={'a/b':{'~key':[10,20]},'':7};assert resolve(d,'/a~1b/~0key/1')==20;assert resolve(d,'/')==7;assert resolve(d,'') is d
for p in ['x','/a~2b','/a~1b/~0key/01','/a~1b/~0key/-1','/missing']:
 try: resolve(d,p)
